package com.mdiaz.trxlauncher;
import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.widget.*;import java.util.*;
final class AppsScreen extends ScrollView{
 private final MainActivity a;AppsScreen(MainActivity c){super(c);a=c;setFillViewport(true);show(0);}
 private void show(int tab){removeAllViews();LinearLayout root=Ui.col(a);root.setPadding(24,18,24,22);addView(root);root.addView(Ui.text(a,"PRECISION APPS",11,Ui.RED,true));root.addView(Ui.text(a,"Every app, without the clutter.",32,Color.WHITE,true));root.addView(Ui.tabs(a,new String[]{"All","Driving","Media","Tools"},tab,this::show),new LinearLayout.LayoutParams(-1,76));EditText search=new EditText(a);search.setHint("Search all apps");search.setTextColor(Color.WHITE);search.setHintTextColor(0xff999da4);search.setBackground(Ui.bg(Ui.CARD,0xff3b3e44,18,a));search.setPadding(24,0,24,0);root.addView(search,new LinearLayout.LayoutParams(-1,64));GridLayout grid=new GridLayout(a);grid.setColumnCount(4);List<ResolveInfo> apps=a.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);apps.sort(Comparator.comparing(x->x.loadLabel(a.getPackageManager()).toString().toLowerCase()));for(ResolveInfo info:apps){String label=info.loadLabel(a.getPackageManager()).toString();Button b=Ui.button(a,label,false);b.setOnClickListener(v->{Intent i=a.getPackageManager().getLaunchIntentForPackage(info.activityInfo.packageName);if(i!=null)a.startActivity(i);});grid.addView(b,new GridLayout.LayoutParams(){ {width=0;height=Ui.dp(a,110);columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(6,6,6,6);} });}root.addView(grid);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){for(int i=0;i<grid.getChildCount();i++){Button v=(Button)grid.getChildAt(i);v.setVisibility(v.getText().toString().toLowerCase().contains(s.toString().toLowerCase())?VISIBLE:GONE);}}public void afterTextChanged(android.text.Editable e){}});}
}
